milestones.verifier_body:
ads = [c['args'] for c in env_state['calls'] if c['tool'] == 'publish_ad']
assert ads, 'no ads published'
good = {str(a.get('keyword', '')).strip().lower() for a in ads if regex_schema(a.get('headline'), r'[A-Z][^!]{9,59}')}
buy = {str(k).strip().lower() for k in tagged(ground_truth['keyword_intent.csv'], 'BUY', key='keyword')}
assert buy <= good, 'missing or non-compliant ads: %s' % sorted(buy - good)
